package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ledger_entries") public class LedgerEntry{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(optional=false) @JoinColumn(name="ledger_transaction_id") private LedgerTransaction ledgerTransaction;@ManyToOne(optional=false) private TransferAccount account;@Enumerated(EnumType.STRING) @Column(name="entry_type",nullable=false,length=10) private EntryType entryType;@Column(nullable=false,precision=19,scale=4) private BigDecimal amount;@Column(nullable=false,length=3) private String currency;@Column(name="created_at",nullable=false) private Instant createdAt;@PrePersist void create(){createdAt=Instant.now();}public void setLedgerTransaction(LedgerTransaction v){ledgerTransaction=v;}public void setAccount(TransferAccount v){account=v;}public void setEntryType(EntryType v){entryType=v;}public void setAmount(BigDecimal v){amount=v;}public void setCurrency(String v){currency=v;}public enum EntryType{DEBIT,CREDIT}}
